import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Install and manage plugins","description":"","frontmatter":{"title":"Install and manage plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2892162f1f2ec94f8e5072f6689382b3c32c8546f2ad667a4651c721f597e84a","translationRevision":"2892162f1f2ec94f8e5072f6689382b3c32c8546f2ad667a4651c721f597e84a","order":10},"headers":[],"relativePath":"en/user/plugins/index.md","filePath":"en/user/plugins/index.md","lastUpdated":1795727787000}`),s={name:`en/user/plugins/index.md`};function c(a,o,s,c,l,u){let d=e(`TourFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="install-and-manage-plugins" tabindex="-1">Install and manage plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to “Install and manage plugins”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Add an integration, review its requested access and confirm that its actions are usable. You need a desktop package compatible with the plugin&#39;s operating system, architecture and host version. Remote catalog and download operations require network access; some account-based services also require <a href="./../cloud/account.html">Cloud sign-in</a>.</p><h2 id="review-before-enabling" tabindex="-1">Review before enabling <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to “Review before enabling”">​</a></h2><ol><li>Open <strong>Plugins</strong> and inspect Installed, Explore or Updates. Explore requests plugin entries only. Find automation templates and profiles in <a href="./../automations/templates.html">Automations</a>.</li><li>Select a plugin to inspect its description, version, compatibility and runtime. Check the publisher and requested capabilities or permissions rather than trusting a familiar display name alone.</li><li>Use the install flow to inspect the package preview. Review the exact version, signature information, requested access and changes from an installed version before confirming installation.</li><li>Wait for the package job result. Downloading, installing and enabling are distinct stages; a catalog card alone does not mean the runtime is ready.</li><li>Open the plugin&#39;s Settings or Connection pane. Supply its service address and credentials only in the intended fields. Use a declared connection check when offered.</li><li>Enable the plugin, then check whether its action types or pages appear. Create a narrowly scoped <a href="./../automations/first-rule.html">logging rule</a> before attaching a powerful external action.</li></ol><p>Plugins can run native code or separate processes. A process boundary can isolate a crash, but it is not an operating system sandbox. Install software from publishers you trust. A valid signature identifies reviewed package provenance; it does not make every effect appropriate for your workflow.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>Package review, installation jobs, plugin preferences and version management are available. Actual actions depend on the installed manifest, host capabilities and external service. Event processors have their own panel and can add optional analysis fields to events; raw fields remain distinct.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>For installation failure, read the job error for compatibility, signature, runtime or download problems. Do not weaken verification just to clear an error. If an update causes trouble, inspect retained versions and use rollback where available. Review dependent automations before disabling or uninstalling a plugin. Keep <a href="./../preferences/backups.html">backups</a> of plugin data and configuration before removing them.</p>`,10),t(d,{id:`plugin`,locale:`en`,title:`Demo: plugins`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Command line operations <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Command line operations”">​</a></h2><p>Every operation in this guide is also available from the CLI — offline, scriptable and agent-friendly. Usage lines are parser syntax and stay in English in every locale.</p><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>list installed plugins</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>read one plugin</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>install from a file, id@version or url</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>uninstall a plugin <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>search packages in the registry</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>inspect a package spec before installing</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>list installed plugins with available updates</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>update one plugin</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>update every outdated plugin</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>roll back to a previous version <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>list available versions of a plugin</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>pin a plugin to its current version</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>remove the version pin</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>set channel and auto-update policy</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>list package jobs</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>inspect one package job</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>cancel a running package job <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>enable a plugin</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>disable a plugin</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>start a plugin</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>stop a plugin <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>read plugin settings</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>write plugin settings</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>reset plugin settings <strong>destructive</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>plugin health check</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>options of an action type or field</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>run a plugin action</td></tr><tr><td><code>tiktools plugin commands</code></td><td>list commands contributed by installed plugins</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>describe one contributed command</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>invoke a plugin-contributed command</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>list configured registries</td></tr><tr><td><code>tiktools registry refresh</code></td><td>refresh registry metadata</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>show one registry package</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>search the cloud catalog</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>cloud catalog summaries page</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versions of one cloud catalog package</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>pagination capabilities of the cloud catalog</td></tr><tr><td><code>tiktools registry defaults</code></td><td>default registry configuration</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>list processors</td></tr><tr><td><code>tiktools processor status</code></td><td>processor pipeline status</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>run one processor against a sample event</td></tr></tbody></table><p>See the <a href="./../../developer/cli.html">full command reference</a> for conventions, JSON output and destructive-operation markers.</p>`,6)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};